INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0582369b-464a-46bf-a4a7-924053a9d87f', '21feff02-016d-46e2-bb9d-c27495133b1b', '101. óra: Feladatmegoldás', 'Összetett kerületszámítási és kerítésszámítási szöveges feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b674b8d9-59eb-47f4-a252-9ca389ffd7f4", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "2482331f-9bc5-443f-bb8a-347a58fdefeb", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "7516d126-8e7c-47b2-93a0-1b8cfa332d8b", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "f2479c08-a665-441b-9e83-e1226dd05a52", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "f32b5458-f075-4c2e-a340-f7f9691756d7", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "85206fcd-2a74-4abb-9a41-a2d9d98637ca", "text": "Igaz", "isCorrect": true}, {"id": "0d7e0668-1e93-4db1-8806-f59a57662a77", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "cbba0b75-46d8-4fdc-833c-b563581088c1", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "f6b19805-d391-42d0-bfda-027923549461", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "0a6de778-7851-4e5b-ba0e-4d5d630b2828", "text": "Igaz", "isCorrect": true}, {"id": "949c8cd9-594d-49dc-84ad-7c478361a54d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cc35c01e-9a33-4ecc-accb-412b294a5328', '21feff02-016d-46e2-bb9d-c27495133b1b', '102. óra: A terület és a térfogat mérése', 'A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "6c2cbb3e-cfcb-4172-84a9-32326737a0b6", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "ab0c34b3-7727-4d07-815a-fb3808042459", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "fd0f3532-8ea6-4d5f-b2ed-a71df6f5370c", "text": "Méter (m)", "isCorrect": false}, {"id": "c0ddfdbf-97c0-43d6-a316-7f3184bafa89", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "f4580cb3-2be8-4915-8167-11a90beef092", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "d031fd26-bf4f-427e-be94-102c963e463e", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "9b3b6ff6-fa6b-4698-8175-71795c864790", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "ae75d21e-b845-4536-adf9-41e0a584f77b", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "88f98647-ce27-42da-87b9-32f924bac475", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "df94db39-29c9-462a-9ef7-37eeb0a75985", "text": "Igaz", "isCorrect": true}, {"id": "c3e115ba-cd25-473e-a39b-0b4e94b11859", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "57905937-e89e-4294-9d0e-bc9f52eba1cb", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "3d905214-c2f6-4ef4-a471-eee554a999ca", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "dd1f0960-74b9-4e02-ac1d-830bd237818c", "text": "Igaz", "isCorrect": true}, {"id": "114a09f9-fa74-4dd3-a591-e9ea358e5038", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c23f4e7f-41e8-4df6-8cb7-4e973dea8d2a', '21feff02-016d-46e2-bb9d-c27495133b1b', '103. óra: Gyakorlóóra. A terület és a térfogat mérése', 'Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "bb088489-8b9c-48fd-924e-328c32625b7b", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e837cd70-3e96-47a6-97ff-70b2b89aa2c3", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "c9494c6b-d929-478e-baee-f9492500a536", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "34491b96-26af-4d83-86d4-6c6882cdf423", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "893f5979-0025-49d8-8802-893ed378a90d", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "921643fd-f701-48c6-9065-8b990901e708", "text": "Igaz", "isCorrect": true}, {"id": "9d51c4fc-13de-4558-82aa-42c13138e373", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e24bb7c1-90a8-40c0-b30c-9d63eb6c09fc", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "c9eb4b5d-5981-4f33-93a4-141fd6738ceb", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9e2c29fb-2580-4d27-8942-a80bf63cadb5', '21feff02-016d-46e2-bb9d-c27495133b1b', '104. óra: A sokszögek területe', 'Négyzet, téglalap és derékszögű háromszög területe (T).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "30e4fef1-2ed7-41f1-b41b-216fcd0c4638", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "949638c4-3c9a-45ea-9d29-7eb310ec4310", "text": "T = a * b", "isCorrect": true}, {"id": "bda38dd5-8b03-4bce-bb9f-c9b4cfe52a6f", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "1b6d15d2-173e-4e69-b4dd-adaac1610edd", "text": "T = a + b", "isCorrect": false}, {"id": "8d5e89c1-7a94-4357-a538-47cfd63cc561", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "93f30055-abef-4dc3-91a7-6ccb40b2b59f", "text": "Mi a négyzet területének képlete (''a'' oldallal)?", "type": "multiple-choice", "options": [{"id": "acd68142-f09d-4848-85f8-11e740e16770", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "b0bfe17e-a662-456e-a724-24b487ea4398", "text": "T = 4 * a", "isCorrect": false}, {"id": "a9912764-6eae-422d-834c-714cb42199f1", "text": "T = 2 * a", "isCorrect": false}, {"id": "a7d02f89-92ec-468d-897d-6f52dd1d3df3", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "32654e2f-a0d9-4b32-b4d1-3418608b717a", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "d9b1eedc-8b0a-4f81-953c-e590dc595659", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "d928b4b9-be46-4846-8388-9c16e32d2b24", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "06c00b67-d923-4c5a-86de-70b67dac28cf", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "340011cd-08f0-4de6-9a6c-09c9c38f2fe5", "text": "T = a * b", "isCorrect": false}, {"id": "a0e6d661-324c-43e4-aa16-5a8f5d9941ce", "text": "T = a + b", "isCorrect": false}, {"id": "42ae83b9-6240-48d3-9da2-d5b12345849b", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "8589de93-c15b-4c03-9eb8-89f392a75cb5", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "8144b03a-34ce-4ce7-8a47-c8c318b9bcd0", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "d4806075-20f5-4c3f-ad39-82168a9be2d3", "text": "Igaz", "isCorrect": true}, {"id": "cd3b565c-3202-4ded-935a-1480c088cb4c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f03fa68e-8bf9-43d7-9f92-f57695078895', '21feff02-016d-46e2-bb9d-c27495133b1b', '105. óra: Feladatmegoldás', 'Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e1ed7df5-91ea-4117-9522-78d7ba77c3c3", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "07e59a21-0a32-4f81-b9d5-f0b5a7ea39b9", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "0eebb391-8e5a-40dd-ad33-967ec295cd7c", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "4966aa61-edb0-4042-8d9e-dc7a2fd1989e", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "2588f80e-d575-4c84-bb88-b8439baaeacc", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "333f743c-fba9-4639-964d-fa20aad805a3", "text": "Igaz", "isCorrect": true}, {"id": "05b4f3af-539a-49f2-8d3d-93526caf9711", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9e09215b-7c5d-4c5d-a3b2-39b7af96e1f4", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "9fe7c1a5-613f-4aeb-8732-f5b6dd18f6de", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "fac125d2-36b9-45da-bbae-9bc22edd17d8", "text": "Igaz", "isCorrect": true}, {"id": "82649f80-835b-4525-ae19-40396f738d6d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4a6ec4de-9e81-4bd9-8015-93257ce1413f', '21feff02-016d-46e2-bb9d-c27495133b1b', '106. óra: Alakzatok a térben', 'Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "80447423-2313-4f86-97ad-b930a96c23e6", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "23030250-eb6c-4c63-8926-7d99a38a4877", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "81507c2a-d7a7-40e4-b9bd-6e943c20585e", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "150780d0-e8be-496a-989d-0281ba5d9aca", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "10ee5967-def3-4c9e-9aab-5bc45b19ddda", "text": "Igaz", "isCorrect": true}, {"id": "999165b7-52d5-4646-9f78-545041a82cf6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1d5afa2e-7e48-4585-93ec-56d4a7e9d49b", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "b19d365c-e62b-4f81-84de-11cc0b2e3967", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "d71aa2ae-d8aa-4753-88d8-1ef7f3128ce6", "text": "Háromszögek", "isCorrect": false}, {"id": "b669ea69-c5bc-4b31-a3da-676376a4f1f2", "text": "Körök", "isCorrect": false}, {"id": "fa31e848-8339-4575-9190-2458a4181da6", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "9773c88c-5cde-4ded-8c4d-40b02e291937", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "e70c4882-d3d7-49c7-804d-5c09aea665f4", "text": "Igaz", "isCorrect": true}, {"id": "14843b57-f6fe-43db-a2df-b005d0e32df2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8a5b22b7-cbb9-4113-87fd-c79e2e549227", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('01588ae8-fdf1-4352-b718-6cd10c033c1e', '21feff02-016d-46e2-bb9d-c27495133b1b', '107. óra: Testek felszíne', 'Kocka és téglatest felszínének kiszámítása (A vagy F).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "ced3fb9e-2843-4c7b-bed7-30a90d8932d8", "text": "Mi a kocka felszínének képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "7b5788b3-8813-4cf9-8047-7c3ef2a0f213", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "70f96e3a-e6a3-4555-90a4-978e81e67e1f", "text": "F = a * a * a", "isCorrect": false}, {"id": "6eccdbd6-2e4e-4c18-975b-8791f17d2d0e", "text": "F = 12 * a", "isCorrect": false}, {"id": "b7022637-0ea4-41b3-8005-0f867adc7426", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "c4367cd3-c34e-4517-8da7-09ba2aa977eb", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "0c6f0581-f5b0-4a33-b4be-e6f8997c3152", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "818a6e83-e64d-45dd-bd37-ba60a4df6860", "text": "F = a * b * c", "isCorrect": false}, {"id": "81393efa-8ca5-4f46-a6b7-4420ae0c710d", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "240f51c0-f41e-4fa6-bd41-ad15d75fd0cb", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "10a78186-e64e-498e-b814-9b20540ae6e4", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "0741c47e-8bf7-4aaa-9a59-5c3c04660852", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "723591fc-38b9-4191-b061-e62ac2640b32", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "9a3e81f0-7dbc-4b73-a5e4-a470ba24d8ec", "text": "Igaz", "isCorrect": true}, {"id": "b7566033-ac57-4630-94d1-b63e69b830a5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c5232a2f-1dd9-4bf4-abac-70c3273cd234", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "c8e841b2-2af8-4c3a-8001-7812dc147f27", "text": "Igaz", "isCorrect": true}, {"id": "a261b1ce-0f9c-47ac-85b3-8b21306b8aca", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "efe221dc-067d-4ca3-9af5-ad691ba8b9c4", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('fcbf8c76-6917-4532-bda0-4c88e70bf590', '21feff02-016d-46e2-bb9d-c27495133b1b', '108. óra: Gyakorlóóra', 'Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "3a8bfd77-0735-4341-8353-b7bbd18714d4", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "0a0a3382-270f-4c29-9a58-38109b912f43", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "085bbaf4-7f5b-4f61-86ed-cfbfe48df61c", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "e322901c-8574-4b7c-9e4d-7295d637f37f", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "97da3ac0-8286-493c-a1e6-505b497fd22f", "text": "Igaz", "isCorrect": true}, {"id": "a90ee25c-ab6a-4d29-b721-c3f18830f224", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "45dcd548-a5be-4dde-8c17-2fcb7f60ca09", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "526e2d6b-2d6f-4661-ad21-63c2e108a8d5", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "561ea573-baca-4ce4-97cd-7e1bf603035d", "text": "Igaz", "isCorrect": true}, {"id": "53c635e2-590b-4a09-81fd-548d596dea91", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3b186535-a243-4ef8-8697-999b40d1c0f0", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "8f729b55-4722-4417-8bf6-1d8d696a9c3c", "text": "Igaz", "isCorrect": true}, {"id": "a5ddd8b1-cea7-4ed2-a1e1-aee23f443181", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('14ff5fce-75f3-4b43-9deb-ede152c367d6', '21feff02-016d-46e2-bb9d-c27495133b1b', '109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok', 'Dobozok lefestése, csomagolópapír szükséglet kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "48a163e1-81ef-424e-b66e-8d657abae0eb", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "2616cd59-c140-4674-ba3a-4536a17d5732", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "b677bc3f-fe3a-48ca-9cb3-ee41be7f937d", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "7a8c9f71-14fb-46bb-a67d-6e4a43fa915e", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "ec56b6c8-c5bb-4d25-a0db-a8d2608f1b31", "text": "Igaz", "isCorrect": true}, {"id": "ade7d45f-3149-45b6-be9f-2a695af7bd94", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "de2a838e-a7a3-489b-b0a1-e23b3d013ca2", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "8beda491-b9cb-47ca-b3de-3ff9c5e4cace", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "c0f82abb-a6b9-441b-9b85-aa125afa913d", "text": "Igaz", "isCorrect": true}, {"id": "e785f32c-c5b1-46ef-b264-e112ac25afbc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec075094-6068-456d-8942-226a244b45f6", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8f21de9e-80df-455f-913f-4298459e21a3', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "b0f3fb2b-a768-4b50-b500-c6a85dc224c2", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "de1784d5-69b8-4f36-80b1-40fc2fe790d9", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "ca9358f4-ee79-4dda-8a83-3116373429f7", "text": "V = 6 * a²", "isCorrect": false}, {"id": "06788541-3b29-4878-aefa-fd2a1021e8c1", "text": "V = 12 * a", "isCorrect": false}, {"id": "96da0a55-ff98-4b54-b40c-01633b6b45a7", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "4083cc11-06f1-4317-b17f-23e14db3cddf", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "d7fdc6ad-0313-4886-9e6a-2f0e012db925", "text": "V = a * b * c", "isCorrect": true}, {"id": "3954671c-fc16-4722-a6cd-3c3da0b6f702", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "25323b29-ee74-42e3-8563-0aadb34e8bfb", "text": "V = a * b", "isCorrect": false}, {"id": "a81a787b-da49-4b61-bcce-ceea85b4b109", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "6023fabb-5c40-436f-a4de-bdb876533c87", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "f8eb3574-86f9-4eb1-9fa8-1a432a337c06", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "3426d329-8083-49bf-a81e-7eccee4ff1ec", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "c487a47d-3866-4e1b-b865-44516524874c", "text": "Igaz", "isCorrect": true}, {"id": "639c4d0d-82a8-443c-afad-e7160abf92a0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8d8f968a-8c94-49b0-b20a-f8fd82c26ded", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "eab26958-a310-4c0a-8ab8-de844b3c6870", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;